-- 0019_recording_import_2026_09_28.sql
-- Bulk-adds real member recordings from Nina's Google Drive export (2026-09-28),
-- filling gaps found by comparing sonario.recordings against sonario.songs/part_labels.
-- Also fixes a real pre-existing bug: That's Freedom's 'tenor' row was actually the
-- full-choir mix (file size matched 'That's freedom - All.m4a' exactly, not the real
-- tenor file), so tenors were hearing the whole choir in Practice Mode. Uploaded to
-- Storage via `supabase storage cp` before this ran; see the paired chat log for the
-- exact source filenames per row.

update sonario.recordings set part_label = 'full_choir'
  where song_id = 'b0000000-0000-0000-0000-00000000000e' and part_label = 'tenor';

